import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.every.js";
import "core-js/modules/es.iterator.map.js";
import { VueEditor } from "vue3-editor";
import { update_list_email_templates } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar,
    VueEditor
  },
  data() {
    return {
      ccEmails: [],
      selectedItem: null,
      search: "",
      subjectValue: "",
      dropdownItems: [{
        title: "Total Amount",
        value: "{{total_amount}}"
      }, {
        title: "Quatation Number",
        value: "{{quatation_no}}"
      }, {
        title: "Customer Name",
        value: "{{customer_name}}"
      }, {
        title: "Entity Name",
        value: "{{entity_name}}"
      }, {
        title: "Entity Address",
        value: "{{entity_address}}"
      }, {
        title: "Customer Email-ID",
        value: "{{to_address}}"
      }],
      bodyValue: "",
      loading: false,
      ccError: "",
      bodyError: "",
      SnackBarComponent: {},
      customToolbar: [["bold", "italic", "underline", "strike"], ["blockquote", "code-block"], [{
        header: 1
      }, {
        header: 2
      }], [{
        list: "ordered"
      }, {
        list: "bullet"
      }], [{
        script: "sub"
      }, {
        script: "super"
      }], [{
        indent: "-1"
      }, {
        indent: "+1"
      }], [{
        direction: "rtl"
      }], [{
        size: ["small", false, "large", "huge"]
      }], [{
        header: [1, 2, 3, 4, 5, 6, false]
      }], [{
        color: []
      }, {
        background: []
      }], [{
        font: []
      }], [{
        align: []
      }], ["clean"], ["link", "image"]],
      editorOptions: {
        placeholder: "Enter email body content...",
        theme: "snow"
      }
    };
  },
  created() {
    this.fetch_templatelist();
  },
  methods: {
    validateEmails(value) {
      const emailPattern = /\S+@\S+\.\S+/;
      return value.every(email => emailPattern.test(email)) || "Enter valid emails";
    },
    onEditorReady(quill) {
      this.quill = quill;
    },
    onEditorInput(html) {
      this.bodyValue = html;
      this.bodyError = "";
    },
    insertSelectedItem() {
      if (this.selectedItem && this.quill) {
        const range = this.quill.getSelection();
        if (range) {
          this.quill.insertText(range.index, this.selectedItem);
        } else {
          this.quill.insertText(this.quill.getLength(), this.selectedItem);
        }
        this.bodyError = "";
      }
    },
    async fetch_templatelist() {
      try {
        let result = await API.graphql(graphqlOperation(update_list_email_templates, {
          input: {
            action_type: "LIST",
            email_template_type: "BILLING"
          }
        }));
        let response = JSON.parse(result.data.update_list_email_templates);
        if (response.Status === "SUCCESS" && response.data.length > 0) {
          const emailTemplate = response.data[0].email_template;
          this.ccEmails = emailTemplate.cc || [];
          this.subjectValue = emailTemplate.subject || "";
          this.bodyValue = emailTemplate.body || "";
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors?.[0]?.message || "Error fetching template",
          timeout: 5000,
          Top: true
        };
      }
    },
    async validate_actions() {
      const emailBody = this.bodyValue.trim();
      if (!emailBody) {
        this.bodyError = "Email body cannot be empty";
      } else {
        this.bodyError = "";
      }
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid && emailBody) {
        this.loading = true;
        this.saveEmailTemplate();
      }
    },
    async saveEmailTemplate() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(update_list_email_templates, {
          input: {
            action_type: "UPDATE",
            email_template_type: "BILLING",
            email_template: this.all_data_template()
          }
        }));
        let response = JSON.parse(result.data.update_list_email_templates);
        if (response.Status == "SUCCESS") {
          this.loading = false;
          this.fetch_templatelist();
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors?.[0]?.message || "Error fetching template",
          timeout: 5000,
          Top: true
        };
      }
    },
    all_data_template() {
      var data = {
        body: this.bodyValue,
        subject: this.subjectValue,
        cc: this.ccEmails.map(email => email.trim())
      };
      return JSON.stringify(data);
    }
  }
};
